type Loader struct{root context.Context;fetch func(context.Context,string)(int,error);group singleflight.Group}
func NewLoader(root context.Context,fetch func(context.Context,string)(int,error))(*Loader,error){if root==nil||fetch==nil{return nil,errors.New("dependencies required")};return &Loader{root:root,fetch:fetch},nil}
func(l *Loader)Get(ctx context.Context,key string)(int,error){
