 ch:=l.group.DoChan(key,func()(any,error){return l.fetch(l.root,key)})
 select{case <-ctx.Done():return 0,ctx.Err();case result:=<-ch:if result.Err!=nil{return 0,result.Err};return result.Val.(int),nil}
}
