 l,e:=NewLoader(context.Background(),func(ctx context.Context,key string)(int,error){calls.Add(1);started<-struct{}{};select{case <-release:return 42,nil;case <-ctx.Done():return 0,ctx.Err()}});if e!=nil{t.Fatal(e)}
